static char buf[1010];

int main() {
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
//  freopen("output.txt", "w", stdout);
#endif

    int n, m, q;
    scanf("%d %d %d", &n, &m, &q);
    vector<string> tmp(n);
    string s;
    int sum = 0;
    for (int i = 0; i < n; ++i) {
        scanf("%s", buf);
        tmp[i] = buf;
        sum += count(tmp[i].begin(), tmp[i].end(), '*');
    }

    for (int j = 0; j < m; ++j) {
        for (int i = 0; i < n; ++i) {
            s += tmp[i][j];
        }
    }
    int res = count(s.begin(), s.begin() + sum, '.');
    int pos = sum;
    for (int i = 0; i < q; ++i) {
        int x, y;
        scanf("%d %d", &x, &y);
        --x, --y;
        int p = y * n + x;
        if (p < pos) {
            if (s[p] == '.') {
                --res;
            } else {
                ++res;
            }
        }
        s[p] = (s[p] == '.' ? '*' : '.');
        if (s[p] == '*') {
            if (s[pos] == '.') {
                ++res;
            }
            ++pos;
        } else {
            if (s[pos - 1] == '.') {
                --res;
            }
            --pos;
        }
        printf("%d\n", res);
    }

    return 0;
}

